CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name) <= 80), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL, label text NOT NULL DEFAULT 'Web browser', created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days'), revoked_at timestamptz);
GRANT SELECT ON public.account_sessions TO authenticated;
GRANT ALL ON public.account_sessions TO service_role;
ALTER TABLE public.account_sessions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.account_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event text NOT NULL CHECK (event IN ('session_registered','session_revoked','other_sessions_revoked','profile_updated')), occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_activity TO authenticated;
GRANT ALL ON public.account_activity TO service_role;
ALTER TABLE public.account_activity ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.account_session_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.account_sessions s WHERE s.id = nullif(auth.jwt()->>'session_id','')::uuid AND s.user_id = auth.uid() AND s.revoked_at IS NULL AND s.expires_at > now()) $$;
REVOKE ALL ON FUNCTION public.account_session_active() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.account_session_active() TO authenticated;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() AND public.account_session_active());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid() AND public.account_session_active()) WITH CHECK (id = auth.uid() AND public.account_session_active());
CREATE POLICY sessions_read ON public.account_sessions FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.account_session_active());
CREATE POLICY activity_read ON public.account_activity FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.account_session_active());
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_account_profile() FROM PUBLIC;
CREATE TRIGGER account_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE FUNCTION public.profile_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NEW.display_name IS DISTINCT FROM OLD.display_name THEN INSERT INTO public.account_activity(user_id,event) VALUES (NEW.id,'profile_updated'); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.profile_activity() FROM PUBLIC;
CREATE TRIGGER account_profile_activity AFTER UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.profile_activity();
CREATE FUNCTION public.register_account_session() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE sid uuid := nullif(auth.jwt()->>'session_id','')::uuid; uid uuid := auth.uid(); BEGIN IF uid IS NULL OR sid IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id=sid AND user_id=uid) THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF EXISTS(SELECT 1 FROM public.account_sessions WHERE id=sid AND (revoked_at IS NOT NULL OR expires_at <= now())) THEN RAISE EXCEPTION 'Session expired or revoked'; END IF; INSERT INTO public.profiles(id) VALUES(uid) ON CONFLICT DO NOTHING; IF NOT EXISTS(SELECT 1 FROM public.account_sessions WHERE id=sid) THEN INSERT INTO public.account_sessions(id,user_id) VALUES(sid,uid); INSERT INTO public.account_activity(user_id,event) VALUES(uid,'session_registered'); ELSE UPDATE public.account_sessions SET last_seen_at=now() WHERE id=sid AND user_id=uid; END IF; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.register_account_session() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_account_session() TO authenticated;
CREATE FUNCTION public.revoke_account_session(target_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NOT public.account_session_active() THEN RAISE EXCEPTION 'Unauthorized'; END IF; UPDATE public.account_sessions SET revoked_at=now() WHERE id=target_id AND user_id=auth.uid() AND revoked_at IS NULL; IF FOUND THEN INSERT INTO public.account_activity(user_id,event) VALUES(auth.uid(),'session_revoked'); END IF; END $$;
REVOKE ALL ON FUNCTION public.revoke_account_session(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.revoke_account_session(uuid) TO authenticated;
CREATE FUNCTION public.revoke_other_account_sessions() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF NOT public.account_session_active() THEN RAISE EXCEPTION 'Unauthorized'; END IF; UPDATE public.account_sessions SET revoked_at=now() WHERE user_id=auth.uid() AND id <> nullif(auth.jwt()->>'session_id','')::uuid AND revoked_at IS NULL; IF FOUND THEN INSERT INTO public.account_activity(user_id,event) VALUES(auth.uid(),'other_sessions_revoked'); END IF; END $$;
REVOKE ALL ON FUNCTION public.revoke_other_account_sessions() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.revoke_other_account_sessions() TO authenticated;